# RW4DM_DELETE: Delete: whole objects and selected control points. The script rw4dm_delete_script.txt is generated by rw4dm_gen.py. The oracle is exact set / string logic on four objects (ids 1..4 = Point, Line, Plane, Box):
# after each step the objects that List reaches are compared, as id:kind:layer[:name], with the expected list exactly (and the printed message lines with their patterns).
RW4_DELETE_OUT=""
sed "s|@TMP@|$TMPW|g" "$HERE/rw4dm_delete_script.txt" > "$TMPW/rw4dm_delete_script.txt"
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  RW4_DELETE_OUT="$(timeout 900 "$BIN" --smoke 60 --script "$TMPW/rw4dm_delete_script.txt" 2>&1)" || { echo "$RW4_DELETE_OUT" | tail -40; echo "FAIL RW4DM_DELETE_run: script exited non-zero"; fail=1; RW4_DELETE_OUT=""; }
else
  RW4_DELETE_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 60 --script "$TMPW/rw4dm_delete_script.txt" 2>&1)" || { echo "$RW4_DELETE_OUT" | tail -40; echo "FAIL RW4DM_DELETE_run: script exited non-zero"; fail=1; RW4_DELETE_OUT=""; }
fi
rw4_delete_block() { awk -v name="$1" '$0 ~ ("Unknown command: RW4BEGIN_" name "$") { on = 1; next } on && /Unknown command: RW4BEGIN_/ { exit } on { print }' <<<"$RW4_DELETE_OUT"; }
# rw4_delete_state STEP EXPECTED DESC [PATTERN...]: the objects listed in the step read exactly EXPECTED ("-" = none); each PATTERN must match a printed line of the step
rw4_delete_state() {
  local blk got name desc pat bad want; name="$1"; want="$2"; desc="$3"; blk="$(rw4_delete_block "$name")"
  got="$({ grep -E '^history: Object [0-9]+ \(' <<<"$blk" || true; } | sed -E "s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*) name '(.*)'\$/\1:\2:\3:\4/; s/^history: Object ([0-9]+) \(([^)]*)\) layer (.*)\$/\1:\2:\3/" | tr '\n' ' ' | sed 's/ $//')"; [ -n "$got" ] || got="-"
  bad=""
  shift 3
  for pat in "$@"; do grep -qE "^history: $pat" <<<"$blk" || bad="$bad [$pat]"; done
  if [ "$got" = "$want" ] && [ -z "$bad" ]; then echo "ok   RW4DM_DELETE_$name: $desc (objects: $got)"
  else echo "FAIL RW4DM_DELETE_$name: $desc (listed '$got', expected '$want'; missing message patterns:${bad:- none})"; fail=1; { grep -E '^history: (Object|!|[A-Za-z]+:)' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}

# rw4_delete_lines STEP REGEX SED EXPECTED DESC SORTFLAG TAG: the lines of the step that match "history: REGEX", with "history: " removed and SED applied, joined by " | " (sorted
# bytewise first when the sixth argument is "sort"), read exactly EXPECTED ("-" = no line)
rw4_delete_lines() {
  local blk got; blk="$(rw4_delete_block "$1")"
  got="$({ grep -E "^history: $2" <<<"$blk" || true; } | sed -E 's/^history: //' | sed -E "$3" | { if [ "${6:-}" = sort ]; then LC_ALL=C sort; else cat; fi; } | paste -sd'|' - | sed 's/|/ | /g')"; [ -n "$got" ] || got="-"
  if [ "$got" = "$4" ]; then echo "ok   RW4DM_DELETE_$1_${7:-lines}: $5 (lines: $got)"
  else echo "FAIL RW4DM_DELETE_$1_${7:-lines}: $5 (got '$got', expected '$4')"; fail=1; { grep -E '^history: ' <<<"$blk" || true; } | head -14 | sed 's/^/     line: /'; fi
}
rw4_delete_state objects "1:curve:Default 2:surface:Default" "Delete of the line (3) and the box (4) removes exactly those two objects" "Deleted 2 object\(s\)"
rw4_delete_state surface_cv "1:curve:Default 2:surface:Default" "Delete with the control points of a surface selected is refused with the reason and the surface stays" "Delete: Surface control points cannot be deleted"
rw4_delete_state cleanup "1:curve:Default 2:surface:Default" "the three extracted points are ordinary objects: Delete removes them (3 objects)" "Deleted 3 object\(s\)"
rw4_delete_state cv_all "2:surface:Default" "Delete with every control point of the polyline selected removes the object itself" "Deleted 3 sub-object\(s\), 1 object\(s\) removed entirely"
rw4_delete_state new_resets "1:curve:Default" "(frame path: the script runner draws a frame between lines, which already drops picks of absent objects) control points of a surface picked before New do not turn a later Delete of a new object (same id 2) into a control-point delete - the plane is deleted whole" "Deleted 1 object\(s\)"
rw4_delete_state undo_prunes "1:curve:Default" "(frame path, see new_resets) control points of a new plane (3) are picked, Undo removes the plane, Redo brings it back, and Delete then deletes it whole (it is not refused as a control-point delete)" "Deleted 1 object\(s\)"
rw4_delete_state one_line_new "1:curve:Default" "ONE input line (no frame between): control points of a plane (id 2) are picked, New, a new polyline (1) and plane (2) are made and Delete is called on the new plane: the pick must not survive New, so the plane is deleted whole" "Deleted 1 object\(s\)"
rw4_delete_state one_line_open "1:curve:Default" "ONE input line: control points of a plane (2) are picked, a saved document with the same ids is opened and Delete is called on its plane (2): the pick must not survive Open, the plane is deleted whole" "Deleted 1 object\(s\)"
rw4_delete_state one_line_undo "1:curve:Default" "ONE input line: control points of a plane (2) are picked, Undo removes the plane, Redo brings it back, Delete is called: Undo dropped the picks of the plane it removed, so the plane is deleted whole" "Deleted 1 object\(s\)"
rw4_delete_state one_line_range "-" "ONE input line: all 5 control points of a polyline are picked, then ReducePolyline (5 -> 3 control points), Undo (back to 5), SelControlPoint (5 picks), Redo (3 again): Redo dropped the two picks with an index that no longer exists, so Delete removes 3 sub-objects (all that are left) and with them the object" "Deleted 3 sub-object\(s\), 1 object\(s\) removed entirely"
rw4_delete_state guard_range "-" "two control points (index 3 and 4) of a 5-point polyline are picked, ReducePolyline leaves 3 control points (picks out of range), Delete then deletes the polyline as an object (the out-of-range picks are not a control-point delete)" "Deleted 1 object\(s\)"
rw4_delete_lines cv_mid "  [-0-9.e+]+,[-0-9.e+]+,[-0-9.e+]+$" "s/x/x/" "  0,0,0 |   6,1,0 |   8,0,0" "the control points left after the delete are the original first, fourth and fifth, unchanged" nosort lines
rw4_delete_lines cv_mid "Deleted [0-9]+ sub-object" "s/x/x/" "Deleted 2 sub-object(s)" "Delete reports the two control points it removed" nosort message
